import React, { useState, useRef, useEffect, useMemo } from "react"
import { motion } from "framer-motion"
import { addPropertyControls, ControlType } from "framer"
// The font is EMBEDDED (CAL_SANS_WOFF2, at the end of this file): Cal Sans 2.011 from
// calcom/sans, subset to Latin with every axis and layout feature kept (the GEOM rclt
// swaps and the sets need them). No shared module, no CDN: 175 KB of woff2 instead of
// the 1.19 MB TTF from jsDelivr, and the face is there on first paint.
const CAL_SANS_FONT = {
    family: "Cal Sans 2 embedded",
    version: "Version 2.011; 5a149ee7 (embedded Latin subset)",
}
const FONT_FACE_CSS = () =>
    ["normal", "italic"]
        .map(
            (style) =>
                `@font-face{font-family:"${CAL_SANS_FONT.family}";src:url(${CAL_SANS_WOFF2}) format("woff2");` +
                `font-weight:400 700;font-style:${style};font-display:block}`
        )
        .join("\n")

// GEOM interaction ranges. Mouse-Y SNAPS to one of the v2 GEOM presets (VISION §2):
// A11y=0 / UI=25 / Base=50 / Geo=100. Each range spans the presets inside it; `rows`,
// `families`, and `stops` are parallel (one entry per snap row). `stops[0]` is the
// resting GEOM before any hover.
const GEOM_RANGES = {
    "0-50": { rows: 3, families: ["A11y", "UI", "Base"], stops: [0, 25, 50] },
    "0-100": {
        rows: 4,
        families: ["A11y", "UI", "Base", "Geo"],
        stops: [0, 25, 50, 100],
    },
    "25-50": { rows: 2, families: ["UI", "Base"], stops: [25, 50] },
}

// Shown instead of "Cal Sans" while the SHRP axis is being dragged (one per drag).
const SHARP_WORDS = [
    "57 zigs",
    "75 zags",
    "low viz",
    "wavy vibe",
    "51,997 views",
]

// Draggable sticker: springs in once `show` is true, drag to reposition, with
// hover/tap/drag feedback. Shared by both stickers so behavior is identical;
// each owns an independent random rotation. Falls back to `fallback` when blank.
const Sticker = React.memo(function Sticker({
    text,
    fallback,
    color,
    fontSize,
    family,
    show,
    left,
    top,
    z = 100,
    onGrab,
}) {
    const [rotation, setRotation] = useState(0)
    useEffect(() => {
        setRotation(Math.random() * 40 - 20)
    }, [])
    return (
        <motion.div
            drag
            dragSnapToOrigin={false}
            onPointerDown={onGrab}
            initial={{ opacity: 0, scale: 0, rotate: rotation }}
            animate={{
                opacity: show ? 1 : 0,
                scale: show ? 1 : 0,
                rotate: rotation,
            }}
            transition={{ type: "spring", stiffness: 260, damping: 20 }}
            whileHover={{ scale: 1.1, rotate: rotation + 2, cursor: "grab" }}
            whileTap={{ scale: 0.95, cursor: "grabbing" }}
            whileDrag={{ scale: 1.2, zIndex: 999 }}
            style={{
                position: "absolute",
                left,
                top,
                x: "-50%",
                y: "-50%",
                backgroundColor: color,
                color: "#FFFFFF",
                padding: "0.4em 1em",
                borderRadius: "12px",
                fontSize: `${fontSize}px`,
                fontWeight: 700,
                fontFamily: `"${family}", sans-serif`,
                lineHeight: 1.15,
                // pre, not nowrap: still never wraps on its own, but a line break in
                // the text (the touch legend) starts a new line.
                whiteSpace: "pre",
                textAlign: "center",
                transformOrigin: "center center",
                boxShadow: `0 8px 24px ${color}40`,
                zIndex: z,
                pointerEvents: "auto",
            }}
        >
            {(text || "").trim() || fallback}
        </motion.div>
    )
})

// Die-cut "violator" sticker: the wordmark's own letterforms with a thick outline
// keyline (like a peeled vinyl sticker) + a soft lift shadow — no box. Rendered as
// SVG text so the keyline can use ROUND joins/caps (HTML -webkit-text-stroke is
// miter-only → spikes off sharp vertices like the `v`). The stroke is painted UNDER
// the fill (paint-order) so only the outer halo shows; adjacent glyphs' halos merge
// into one rounded silhouette. Cal Sans SHRP 100 + `titl`.
const VIOLATOR_FVS = `"wght" 700, "SHRP" 100, "opsz" 45` // opsz pinned: STICKER_SDF is baked at 45
const VIOLATOR_FEAT = `"titl" 1`

// STICKER SHAPE for the WebGL foil — the bubbbly approach: the die-cut lives in a
// texture, so the shader draws its own shape and needs no SVG mask. (Safari never
// applies an SVG mask to a canvas in a <foreignObject>; this is what lets it run
// the shader at all.) A two-channel signed distance field of "v2.000" set in Cal Sans
// 2 with VIOLATOR_FVS / VIOLATOR_FEAT, centred on the text anchor (text-anchor
// middle, dominant-baseline central), ±halfX × ±halfY em, 64 px/em, lossless WebP:
//   R = distance to the glyph edge, ±fine em        → the letters
//   G = distance, coarseMin…coarseMax em             → die-cut = letters grown by outlineW
// Distances are in em, so one bake fits every font size and outline width.
// Baked IN SAFARI: Safari and Chrome pick
// different glyphs for this text (the "." and "v" advances differ), and only WebKit
// uses the texture — Chrome keeps clipping the canvas with the SVG masks as before.
// Rebake if the text or its axes change; until then a different text falls back to
// the SVG mesh on Safari.
const STICKER_SDF_META = {
    text: "v2.000",
    halfX: 4.8,
    halfY: 3.2,
    fine: 0.08,
    coarseMin: -0.3,
    // the baked text's own box, em from the anchor — matched at runtime to the box
    // the browser lays out, so small layout differences don't show as a rim
    bboxCX: 0.00000,
    bboxCY: 0.00000,
    bboxW: 3.74707,
    coarseMax: 2.6,
}
const STICKER_SDF =
    "data:image/webp;base64,"

