    cursorType: "crosshair",
    showLeftBorder: true,
    showRightBorder: true,
    borderColor: "#E5E5E5",
    stickerText: "",
    stickerColor: "#7C00F6",
    stickerScale: 100,
    stickerText2: "v2.000",
    stickerColor2: "#242424",
