    geomRange: "0-50",
    idleGeom: 25,
    debug: false,
    lines: "1",
    stickerHolo: "webgl",
    foilPreset: "grating",
    foilBase: "#5a5a63",
    foilChroma: 1,
    foilGrainPx: 2,
    foilGlossRadius: 2.4,
    foilShininess: 1.8,
    foilBandFreq: 14.0,
    starBandFreq: 14,
